import{_ as s,o as r,c as n,l as t,t as a,N as o}from"./chunks/framework.Gjrf2Eoj.js";const u=JSON.parse('{"title":"process-keyring | x-cmd man (man7) | per-process shared keyring","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | process-keyring - per-process shared keyring","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"process-keyring | x-cmd man (man7) | per-process shared keyring"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | process-keyring - per-process shared keyring"}]]},"headers":[],"params":{"isMan":true,"man":"process-keyring","category":"man7","desc":"per-process shared keyring"},"relativePath":"man7/process-keyring.md","filePath":"man7/process-keyring.md"}'),i={name:"man7/process-keyring.md"},c={class:"visually-hidden"},g=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>process-keyring - per-process shared keyring</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The process keyring is a keyring used to anchor keys on behalf of a process. It is created only when a process requests it. The process keyring has the name (description) <em>_pid</em>.</p><p>A special serial number value, <strong>KEY_SPEC_PROCESS_KEYRING</strong>, is defined that can be used in lieu of the actual serial number of the calling process&#39;s process keyring.</p><p>From the <strong>keyctl</strong>(1) utility, &#39;<strong>@p</strong>&#39; can be used instead of a numeric key ID in much the same way, but since <strong>keyctl</strong>(1) is a program run after forking, this is of no utility.</p><p>A thread created using the <strong>clone</strong>(2) <strong>CLONE_THREAD</strong> flag has the same process keyring as the caller of <strong>clone</strong>(2). When a new process is created using <strong>fork</strong>() it initially has no process keyring. A process&#39;s process keyring is cleared on <strong>execve</strong>(2). The process keyring is destroyed when the last thread that refers to it terminates.</p><p>If a process doesn&#39;t have a process keyring when it is accessed, then the process keyring will be created if the keyring is to be modified; otherwise, the error <strong>ENOKEY</strong> results.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>keyctl</strong>(1), <strong>keyctl</strong>(3), <strong>keyrings</strong>(7), <strong>persistent-keyring</strong>(7), <strong>session-keyring</strong>(7), <strong>thread-keyring</strong>(7), <strong>user-keyring</strong>(7), <strong>user-session-keyring</strong>(7)</p>',10);function p(e,h,l,d,m,y){return r(),n("div",null,[t("h1",c,a(e.$params.man),1),g])}const _=s(i,[["render",p]]);export{u as __pageData,_ as default};
